<h1>فرم‌ساز شناخت‌نامه</h1>
<p class="muted">ساختار شناخت‌نامه را به ترتیب مرحله، گروه، پرسش و گزینه مدیریت کنید.</p>
<div class="grid two">
<section class="card"><h2>افزودن مرحله</h2><form method="post" action="/admin/forms/steps"><?= csrf_field() ?><label>عنوان <input name="title" required></label><label>توضیح <textarea name="description"></textarea></label><label>ترتیب نمایش <input type="number" name="sort_order" value="0"></label><label class="check"><input type="checkbox" name="is_active" value="1" checked> فعال</label><button class="button">ذخیره مرحله</button></form></section>
<section class="card"><h2>افزودن گروه</h2><form method="post" action="/admin/forms/groups"><?= csrf_field() ?><label>مرحله <select name="form_step_id" required><?php foreach ($steps as $step): ?><option value="<?= (int)$step['id'] ?>"><?= e($step['title']) ?></option><?php endforeach; ?></select></label><label>عنوان <input name="title" required></label><label>توضیح <textarea name="description"></textarea></label><label>ترتیب نمایش <input type="number" name="sort_order" value="0"></label><label class="check"><input type="checkbox" name="is_active" value="1" checked> فعال</label><button class="button">ذخیره گروه</button></form></section>
