<?php $qv = $editingQuestion ?? []; $existingOptions = $existingOptions ?? []; ?>
<section class="card"><div class="section-title"><h2><?= $qv ? 'ویرایش پرسش' : 'ساخت پرسش' ?></h2><?php if ($qv): ?><span class="pill"><?= e($qv['step_title'].' / '.$qv['group_title']) ?></span><?php endif; ?></div>
